using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int Price(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeBasketOf10000IsChargedBronzePrice() =>
        Assert.Equal(9500, Price(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverBasketOf10000IsChargedSilverPrice() =>
        Assert.Equal(9000, Price(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldBasketOf10000IsChargedGoldPrice() =>
        Assert.Equal(8500, Price(LoyaltyTier.Gold, 10000));

    // Bronze customer's reduction lands on a whole cent
    [Fact]
    public void S4_BronzeBasketOf7CentsIsChargedWholeCent() =>
        Assert.Equal(7, Price(LoyaltyTier.Bronze, 7));
}

